$('#allowAuthentication').onchange=()=>{$('#authHostsField').hidden=!$('#allowAuthentication').checked};
function syncIsolationFields(){const enabled=$('#allowReversibleState').checked||$('#allowConcurrencyTesting').checked;$('#stateEnvironmentField').hidden=state.mode==='web3'||!enabled;$('#concurrencyLimit').closest('span').hidden=!$('#allowConcurrencyTesting').checked}$('#allowReversibleState').onchange=syncIsolationFields;$('#allowConcurrencyTesting').onchange=syncIsolationFields;syncIsolationFields();
$('#providerForm').onsubmit=async ev=>{ev.preventDefault();const button=$('#saveProvider'),message=$('#providerMessage');button.disabled=true;button.querySelector('span').textContent='保存中';message.textContent='';try{const result=await api('/api/v1/traditional/provider',{method:'PUT',body:JSON.stringify({base_url:$('#providerBase').value.trim(),model:$('#providerModel').value.trim(),api_key:$('#providerKey').value})});$('#providerKey').value='';message.textContent=`已保存 ${result.model}；Native Agent 将在下一次授权任务中启用。`;$('#providerBadge').textContent='CONFIGURED';$('#providerBadge').classList.add('ready');await loadTools();toast('模型 API 已保存到本机 Agent 配置')}catch(e){message.textContent=e.message}finally{button.disabled=false;button.querySelector('span').textContent='保存可选配置'}};
$('#projectSearch').addEventListener('input',renderProjects);
function renderProjects(){const query=$('#projectSearch').value.trim().toLocaleLowerCase(),a=state.engagements.filter(e=>!query||`${e.name} ${e.normalized_target}`.toLocaleLowerCase().includes(query));$('#engagementCount').textContent=query?`${a.length} / ${state.engagements.length} 个项目`:`${a.length} 个项目`;$('#clearRecentProjects').disabled=!state.engagements.length;$('#recentEngagements').innerHTML=a.length?a.map(e=>`<article class="project-row"><button class="project-name" onclick="openProject('${esc(e.id)}')"><strong>${esc(e.name)}</strong><small>${new Date(e.created_at).toLocaleString()} · ${esc(e.normalized_target)}</small></button><span class="domain-label">${e.mode==='web3'?'WEB3':'TRADITIONAL'} · ${esc(e.target_type)}</span><span class="state-badge ${esc(e.status)}">${esc(e.status)}</span><div class="row-actions"><button class="quiet-button" onclick="${e.status==='draft'?'reviewScope':'startRun'}('${esc(e.id)}')">${e.status==='draft'?'确认范围':'开始分析'}</button>${e.mode==='traditional'?`<button class="text-action" onclick="openDeepResearch('${esc(e.id)}')">长期深挖</button><button class="text-action" onclick="openIdentityWorkspace('${esc(e.id)}')">测试账号</button>`:''}<button class="text-action" onclick="renameProject('${esc(e.id)}')">改名</button><button class="text-action danger-text" onclick="archiveProject('${esc(e.id)}')">归档</button></div></article>`).join(''):`<div class="empty-state">${query?'没有匹配的项目，试试其他名称或目标地址。':'这个工作域还没有项目。输入一个或多个已授权目标开始。'}</div>`}
function renderFindings(){
 const v=state.findings.verified,c=state.findings.candidates;
 window.renderCandidateQueue?.(c);
 const visibleCandidates=window.filterCandidateQueue?window.filterCandidateQueue(c):c;
 $('#verifiedCount').textContent=v.length;$('#candidateCount').textContent=c.length;$('#clearRunCandidates').disabled=!c.length||!state.activeRun;
 $('#verifiedFindings').innerHTML=v.length?v.map(f=>`<article class="finding-card" data-finding="${esc(f.id)}"><div><span class="state-badge ready">VERIFIED</span><input class="finding-title-input" value="${esc(f.title)}" aria-label="漏洞标题"><p>${esc(f.impact?.editorial?.description||f.impact?.description||f.target)}</p><small class="finding-lifecycle">${esc({open:'仍存在',fix_claimed:'已声明修复 · 待复测',retest_required:'等待定向复测',reopened:'复测仍可复现',verified_fixed:'负向复测确认修复'}[f.lifecycle_status]||f.lifecycle_status||'仍存在')} · ${esc(f.occurrence_count||1)} 次运行记录</small></div><div class="finding-meta"><input class="severity-input" value="${esc(f.severity)}" aria-label="严重性"><span>${f.evidence_ids?.length||0} EVIDENCE</span></div><div class="record-actions"><button class="quiet-button" onclick="openFindingReportFields('${esc(f.id)}')">影响与报告资料</button><button class="quiet-button" onclick="openFindingLifecycle('${esc(f.id)}')">修复与复测</button><button class="quiet-button" onclick="saveVerified('${esc(f.id)}')">保存修改</button><button class="text-action danger-text" onclick="archiveFinding('${esc(f.id)}')">归档</button></div></article>`).join(''):'<div class="empty-state">本次运行没有通过独立复验的漏洞；这不等于目标绝对安全，请结合上方测试报告与覆盖范围判断。</div>';
 $('#candidateFindings').innerHTML=visibleCandidates.length?visibleCandidates.map(f=>{
  const next=f.next_action||{label:'待审阅',action:'证据与下一步',reason:'读取详情以确认可用验证方法。'};
  const replay=state.propertyReplay[f.id],property=f.mode==='web3'&&f.category==='web3_property_violation',busy=replay?.loading;
  let replaySummary='<span>使用两个独立 fuzz seed 定向重放该属性，比较失败原因与反例稳定性。</span>';
  if(replay?.result)replaySummary=`<strong>${replay.result.stable_failure?'两轮稳定复现':'复现不稳定'}</strong><span>${replay.result.rounds.map(x=>`R${x.round} ${esc(x.status)} · ${esc(x.reason)}`).join('<br>')}</span><small>${esc(replay.result.next_gate)}</small>`;
  else if(replay?.job)replaySummary=`<strong>${esc(replay.job.phase||'准备复测')}</strong><span>${esc(replay.job.completed_requests||0)} / ${esc(replay.job.total_requests||2)} 轮 · ${Math.round((replay.job.progress||0)*100)}%</span><small>${replay.job.status==='cancelling'?'当前 Forge 步骤结束后安全停止。':'任务在后台运行，可以留在本页查看进度。'}</small>`;
  else if(replay?.error)replaySummary=`<strong>属性复测未完成</strong><span>${esc(replay.error)}</span><small>修复本地 Foundry 环境或候选证据后可再次执行。</small>`;
  return `<article class="candidate-row editable-record ${property?'web3-property-candidate':''}" data-finding="${esc(f.id)}"><div class="candidate-main"><div class="candidate-kicker"><span>${esc(next.label)}</span><span>${f.evidence_ids?.length||0} 项来源证据</span></div><h3>${esc(f.title)}</h3><p class="candidate-target">${esc(f.target)}</p><p class="candidate-next-reason">${esc(next.reason)}</p><details class="candidate-editor"><summary>查看判断 / 编辑记录</summary><label>候选标题<input class="finding-title-input" value="${esc(f.title)}" aria-label="候选标题"></label><label>候选判断<textarea class="hypothesis-input" aria-label="候选判断">${esc(f.hypothesis)}</textarea></label><button class="quiet-button" onclick="saveCandidate('${esc(f.id)}')">保存判断</button></details>${property?`<div class="property-replay-summary" aria-live="polite">${replaySummary}</div>`:''}</div><span class="state-badge ${f.status==='reproduced'?'ready':''}">${esc({candidate:'待验证',needs_evidence:'证据不足',reproduced:'已复现'}[f.status]||f.status)}</span><div class="record-actions"><button class="quiet-button" onclick="openCandidateDetail('${esc(f.id)}')">${esc(next.action)}</button>${property?`<button class="primary-action compact replay-property" ${busy?'disabled':''} onclick="replayWeb3Property('${esc(f.id)}')">${busy?'复测中…':f.status==='reproduced'?'再次复测':'两轮定向复测'}</button>${busy&&replay?.job?.status!=='cancelling'?`<button class="quiet-button" onclick="cancelWeb3Property('${esc(f.id)}','${esc(replay.job.id)}')">取消复测</button>`:''}`:''}<button class="text-action danger-text" onclick="archiveFinding('${esc(f.id)}')">归档</button></div></article>`
 }).join(''):`<div class="empty-state">${c.length?'当前筛选没有匹配项。调整分类或清除搜索后查看其他候选。':'本次运行没有待验证候选。测试反馈与覆盖记录仍保留在上方报告中。'}</div>`;
 $('#reportFinding').innerHTML=v.length?v.map(f=>`<option value="${esc(f.id)}">${esc(f.title)}</option>`).join(''):'<option value="">没有 Verified Finding</option>'
}
window.replayWeb3Property=async id=>{state.propertyReplay[id]={loading:true};renderFindings();try{let job=await api(`/api/v1/web3/candidates/${id}/property-replay/jobs`,{method:'POST',body:JSON.stringify({rounds:2})});state.propertyReplay[id]={loading:true,job};renderFindings();while(!['completed','failed','cancelled','interrupted'].includes(job.status)){await new Promise(resolve=>setTimeout(resolve,700));job=await api(`/api/v1/verification-jobs/${job.id}`);state.propertyReplay[id]={loading:true,job};renderFindings()}if(job.status!=='completed')throw new Error(job.error||({cancelled:'属性复测已取消',interrupted:'应用重启，属性复测已中断'}[job.status])||'属性复测失败');const result=job.result;state.propertyReplay[id]={result,job};const findings=await api(`/api/v1/findings?mode=web3&run_id=${state.activeRun?.id||''}`);state.findings=findings;renderFindings();toast(result.stable_failure?'两轮属性复测稳定重现，已追加证据':'两轮结果不一致，已标记人工复查');return result}catch(error){state.propertyReplay[id]={error:error.message};renderFindings();toast(error.message);return null}};
window.cancelWeb3Property=async(id,jobId)=>{try{const job=await api(`/api/v1/verification-jobs/${jobId}/cancel`,{method:'POST'});state.propertyReplay[id]={loading:true,job};renderFindings();toast('已请求取消；当前 Forge 步骤结束后停止')}catch(error){toast(error.message)}};
async function refresh(){const refreshMode=state.mode;try{const q=`?mode=${refreshMode}`,[e,r,f,t]=await Promise.all([api('/api/v1/engagements'+q),api('/api/v1/runs'+q),api('/api/v1/findings'+q),api('/api/v1/task-center'+q)]);if(refreshMode!==state.mode)return;state.engagements=e;state.runs=r;state.taskCenter=t;if(!state.activeRun&&r.length)state.activeRun=r[0];else if(state.activeRun)state.activeRun=r.find(x=>x.id===state.activeRun.id)||r[0]||null;state.findings=state.activeRun?{verified:f.verified.filter(x=>x.run_id===state.activeRun.id),candidates:f.candidates.filter(x=>x.run_id===state.activeRun.id)}:f;state.runDetails=state.activeRun?await api(`/api/v1/runs/${state.activeRun.id}/details`):null;if(refreshMode!==state.mode)return;renderProjects();renderRunSelectors();renderTaskCenter();renderFindings();renderRun();if(state.activeRun)Promise.all([loadRunReport(state.activeRun.id),loadHttpWorkbench(),loadAssetGraph()]);else loadAssetGraph();if(r.some(x=>['queued','running','paused'].includes(x.status)))poll()}catch(e){if(refreshMode===state.mode)toast(e.message)}}
$('#analysisForm').onsubmit=async ev=>{ev.preventDefault();$('#analysisError').textContent='';const targets=[...new Set($('#targetInput').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];if(targets.length>20)return $('#analysisError').textContent='单次最多添加 20 个目标';const stamp=new Date().toLocaleString('zh-CN',{hour12:false}).replaceAll('/','-'),prefix=$('#engagementName').value.trim(),oastHosts=[...new Set($('#oastAllowedHosts').value.split(/\r?\n/).map(x=>x.trim().toLowerCase()).filter(Boolean))],authHosts=[...new Set($('#authAllowedHosts').value.split(/\r?\n/).map(x=>x.trim().toLowerCase()).filter(Boolean))],reversible=state.mode==='traditional'&&$('#allowReversibleState').checked,concurrent=state.mode==='traditional'&&$('#allowConcurrencyTesting').checked;try{state.pending=[];for(const [index,target] of targets.entries()){const resolved=await api('/api/v1/targets/resolve',{method:'POST',body:JSON.stringify({target,mode:state.mode})}),base=prefix||(resolved.normalized_target.split('/').filter(Boolean).at(-1)||resolved.normalized_target),name=`${base}${targets.length>1?` #${index+1}`:''}${$('#appendTimestamp').checked?` · ${stamp}`:''}`;const engagement=await api('/api/v1/engagements',{method:'POST',body:JSON.stringify({target,mode:state.mode,name,scope:{notes:$('#scopeNotes').value.trim(),allow_subdomains:state.mode==='traditional'&&$('#allowSubdomains').checked,allow_third_party_passive:state.mode==='traditional'&&$('#allowPassiveThirdParty').checked,allow_oast:state.mode==='traditional'&&$('#allowOast').checked,oast_allowed_hosts:state.mode==='traditional'&&$('#allowOast').checked?oastHosts:[],allow_authentication:state.mode==='traditional'&&$('#allowAuthentication').checked,auth_allowed_hosts:state.mode==='traditional'&&$('#allowAuthentication').checked?authHosts:[],allow_reversible_state_change:reversible,allow_concurrency_testing:concurrent,environment_class:(reversible||concurrent)?$('#stateEnvironment').value:'production'},policy:{max_requests:Number($('#requestBudget').value),max_runtime_minutes:Number($('#runtimeBudget').value),max_concurrency:concurrent?Number($('#concurrencyLimit').value):2,allow_state_change:reversible}})});state.pending.push(engagement)}$('#scopeState').textContent=`已建立 ${state.pending.length} 个独立项目 · 等待统一确认`;showScope(state.pending)}catch(e){$('#analysisError').textContent=e.message}};
function showScope(input){const items=Array.isArray(input)?input:[input];state.pending=items;$('#scopeConfirmed').checked=false;const oast=items[0].scope.allow_oast?`允许 · ${esc((items[0].scope.oast_allowed_hosts||[]).join(', ')||'仅本机回调')}`:'关闭',auth=items[0].scope.allow_authentication?`允许 · ${esc((items[0].scope.auth_allowed_hosts||[]).join(', ')||'仅目标主域')}`:'关闭',concurrency=items[0].scope.allow_concurrency_testing?`允许 · ${esc(items[0].scope.environment_class)} · 最多 ${esc(items[0].policy.max_concurrency||2)} 并发`:'关闭',stateChange=items[0].scope.allow_reversible_state_change?`允许 · ${esc(items[0].scope.environment_class)} · 每次执行再确认`:'关闭';$('#scopeSummary').innerHTML=`<b>${items.length} 个项目等待授权确认</b><br>${items.map((e,i)=>`${i+1}. ${esc(e.name)} · ${esc(e.normalized_target)}`).join('<br>')}<br><br>Allowed: ${esc(items[0].scope.allowed_actions.join(', '))}<br>Denied: ${esc(items[0].scope.denied_actions.join(', '))}<br>OAST: ${oast}<br>测试账号登录: ${auth}<br>可回滚状态测试: ${stateChange}<br>有界并发测试: ${concurrency}<br>每个目标将生成独立 ScopeSnapshot；最多 4 个任务并发运行。`;$('#scopeDialog').showModal()}
