function launchPayload(engagement){const entered=$('#sourcePath').value.trim(),source=entered||(engagement?.target_type==='repository'&&engagement.normalized_target.startsWith('/')?engagement.normalized_target:''),optional=new Set(JSON.parse(localStorage.getItem('fieldwork-optional-tools')||'[]'));return {execution_mode:'real',include_recon:engagement?.target_type!=='repository',include_code:Boolean(source),source_path:source||null,scan_profile:$('#scanProfile').value,include_strix:optional.has('strix'),include_shannon:optional.has('shannon'),include_native_agent:engagement?.mode!=='web3'&&engagement?.target_type!=='cidr'&&$('#useNativeAgent').checked,fork_rpc_url:$('#forkRpcUrl').value.trim()||null,fork_block_number:$('#forkBlockNumber').value?Number($('#forkBlockNumber').value):null,chain_id:$('#forkChainId').value?Number($('#forkChainId').value):null}}
window.startRun=async id=>{try{const engagement=state.engagements.find(item=>item.id===id),payload=launchPayload(engagement),plan=await api(`/api/v1/engagements/${id}/execution-plan`,{method:'POST',body:JSON.stringify(payload)});state.launch={id,engagement,payload,plan};$('#launchPlanConfirmed').checked=false;$('#executeLaunchPlan').disabled=!plan.ready;const web3Fix=engagement?.mode==='web3'&&plan.blockers.some(x=>['web3_source','fork_rpc','deployment_alignment'].includes(x.id))?`<section class="plan-fix"><div><small>FIX BLOCKERS HERE</small><h3>在此补齐并验证 Web3 部署</h3><p>系统会编译本地源码，读取固定区块 Runtime Bytecode，解析 EIP-1967 Proxy，并生成 ProgramSnapshot。RPC 不会持久化。</p></div><div class="plan-fix-grid"><label>本地 Solidity 源码目录<input id="planSourcePath" value="${esc(payload.source_path||'')}" placeholder="/absolute/path/to/repository"></label><label>HTTPS RPC<input id="planForkRpc" type="url" value="${esc(payload.fork_rpc_url||'')}" placeholder="https://rpc.example"></label><label>合约产物名（可选）<input id="planArtifactContract" value="${esc(state.launch?.artifactContract||'')}" placeholder="Vault"></label><label>固定区块（可选）<input id="planForkBlock" type="number" min="0" value="${payload.fork_block_number??''}" placeholder="latest"></label><label>Chain ID（可选）<input id="planChainId" type="number" min="1" value="${payload.chain_id??''}" placeholder="自动识别"></label></div><button id="retryLaunchPlan" type="button" class="primary-action compact" onclick="retryLaunchPlan()">验证部署并重新检查</button><p id="planFixMessage" class="plan-fix-message" role="status"></p></section>`:'';$('#launchPlanContent').innerHTML=`<section class="launch-plan-summary ${plan.ready?'ready':'blocked'}"><div><small>${plan.ready?'READY TO RUN':'BLOCKED'}</small><h3>${esc(plan.name)}</h3><p>${esc(plan.target)}</p></div><strong>${plan.tools.filter(x=>x.ready).length}/${plan.tools.length} 能力就绪</strong></section>${plan.blockers.length?`<section class="plan-blockers"><div><small>ACTION REQUIRED</small><h3>必须处理</h3></div>${plan.blockers.map(x=>`<article><span>!</span><div><b>${esc(x.message)}</b><small>${x.id==='web3_source'?'选择可编译的 Foundry/Hardhat 项目目录':x.id==='fork_rpc'?'填写授权网络的 HTTPS 只读 RPC':x.id==='deployment_alignment'?'在下方验证 source/compiler/runtime bytecode 与 Proxy Implementation':'完成该前置条件后重新检查'}</small></div></article>`).join('')}</section>`:''}${web3Fix}<section><h3>执行能力</h3><div class="plan-tool-grid">${plan.tools.map(x=>`<article><b>${esc(x.id)}</b><span class="${x.ready?'ok':'warn'}">${x.ready?'READY':'NOT TESTED'}</span><small>${esc(x.version)} · ${esc(x.reason)}</small></article>`).join('')}</div></section><section class="plan-budget"><div><small>请求预算</small><b>${plan.budget.requests} · ${plan.budget.requests_per_second} req/s</b></div><div><small>运行上限</small><b>${plan.budget.runtime_minutes} 分钟</b></div><div><small>工具 / 模型</small><b>${plan.budget.tool_calls} calls · $${plan.budget.model_usd}</b></div><div><small>身份覆盖</small><b>${plan.identities.ready}/${plan.identities.total}</b></div></section>${plan.warnings.length?`<section><h3>覆盖提醒</h3>${plan.warnings.map(x=>`<p class="plan-warning">${esc(x.message)}</p>`).join('')}</section>`:''}<section><h3>禁止动作</h3><p>${plan.denied_actions.map(esc).join(' · ')}</p><small>${esc(plan.disclaimer)}</small></section>`;if(!$('#launchPlanDialog').open)$('#launchPlanDialog').showModal()}catch(e){if(e.message.includes('source')||e.message.includes('RPC')){$('#advancedPanel').hidden=false;$('#web3LaunchConfig').hidden=false}toast(e.message)}};
window.retryLaunchPlan=async()=>{if(!state.launch)return;const button=$('#retryLaunchPlan'),message=$('#planFixMessage'),source=$('#planSourcePath')?.value.trim()||'',rpc=$('#planForkRpc')?.value.trim()||'',artifact=$('#planArtifactContract')?.value.trim()||'',block=$('#planForkBlock')?.value||'',chain=$('#planChainId')?.value||'';$('#sourcePath').value=source;$('#forkRpcUrl').value=rpc;$('#forkBlockNumber').value=block;$('#forkChainId').value=chain;state.launch.artifactContract=artifact;if(!source||!rpc){message.textContent='请先填写本地源码目录与 HTTPS RPC';return}button.disabled=true;button.textContent='正在编译并对齐链上部署…';message.textContent='读取固定区块、Proxy 槽位与 Runtime Bytecode，可能需要数十秒。';try{const result=await api('/api/v1/web3/deployment-alignments',{method:'POST',body:JSON.stringify({engagement_id:state.launch.id,source_path:source,rpc_url:rpc,contract_address:state.launch.engagement.normalized_target,artifact_contract:artifact||null,block_number:block?Number(block):null,expected_chain_id:chain?Number(chain):null})});if(result.status!=='aligned'){message.textContent=`对齐未通过：${result.blockers.join(' · ')}`;toast('本地字节码与链上部署不一致');return}message.textContent=`对齐通过：Chain ${result.chain_id} · Block ${result.block_number} · ${result.artifact_contract}`;toast('部署对齐已生成 ProgramSnapshot');await startRun(state.launch.id)}catch(e){message.textContent=e.message}finally{if(button){button.disabled=false;button.textContent='验证部署并重新检查'}}};
function closeLaunchPlan(showConfig=false){$('#launchPlanDialog').close();if(showConfig){$('#advancedPanel').hidden=false;$('#web3LaunchConfig').hidden=state.mode!=='web3';$('#advancedPanel').scrollIntoView({behavior:'smooth',block:'center'})}}
$('#closeLaunchPlan').onclick=()=>closeLaunchPlan(false);$('#backToLaunchConfig').onclick=()=>closeLaunchPlan(true);
$('#launchPlanForm').onsubmit=async ev=>{ev.preventDefault();if(!state.launch||!$('#launchPlanConfirmed').checked||!state.launch.plan.ready)return;const {id,engagement,payload}=state.launch;try{$('#executeLaunchPlan').disabled=true;state.activeRun=await api(`/api/v1/engagements/${id}/start`,{method:'POST',body:JSON.stringify(payload)});$('#launchPlanDialog').close();go('run');toast(engagement.mode==='web3'?'Web3 全工具链已启动':'真实工具链已启动；降级项将写入 Coverage Ledger');poll()}catch(e){toast(e.message)}finally{$('#executeLaunchPlan').disabled=false}};
function poll(){clearInterval(state.poll);state.poll=setInterval(async()=>{if(!state.activeRun)return;try{const id=state.activeRun.id,[runs,run,coverage,findings,details,tasks]=await Promise.all([api(`/api/v1/runs?mode=${state.mode}`),api(`/api/v1/runs/${id}`),api(`/api/v1/runs/${id}/coverage`),api(`/api/v1/findings?mode=${state.mode}&run_id=${id}`),api(`/api/v1/runs/${id}/details`),api(`/api/v1/task-center?mode=${state.mode}`)]);state.runs=runs;state.activeRun=run;state.coverage=coverage.coverage||[];state.findings=findings;state.runDetails=details;state.taskCenter=tasks;renderRunSelectors();renderTaskCenter();renderFindings();renderRun();renderCoverage();if(!runs.some(x=>['queued','running','paused'].includes(x.status))){clearInterval(state.poll);loadRunReport(id)}}catch{}},1000)}
async function loadCoverage(){if(!state.activeRun)return renderCoverage();try{const data=await api(`/api/v1/runs/${state.activeRun.id}/coverage`);state.coverage=data.coverage||[];renderCoverage()}catch{}}
function runLabel(r){const project=state.engagements.find(e=>e.id===r.engagement_id),status=runStatusText[r.status]||r.status;return `${project?.name||r.engagement_id} · ${status} · ${new Date(r.created_at).toLocaleString()}`}
function renderRunSelectors(){const active=state.runs.filter(r=>['queued','running','paused'].includes(r.status)).length,options=state.runs.map(r=>`<option value="${esc(r.id)}" ${r.id===state.activeRun?.id?'selected':''}>${esc(runLabel(r))}</option>`).join('')||'<option value="">暂无任务</option>';$('#runSelector').innerHTML=options;$('#findingRunSelector').innerHTML=options;$('#activeTaskCount').textContent=`${active} 个运行中 · 上限 4`;$('#contextTaskFact').textContent=`${active} 个活动任务`;}
function renderTaskCenter(){const data=state.taskCenter||{counts:{},items:[]},items=data.items||[],active=items.filter(x=>['queued','running','paused'].includes(x.status));$('#clearTaskCenter').disabled=!items.some(x=>!['queued','running','paused'].includes(x.status));$('#taskCenterSummary').textContent=active.length?`${data.counts.running||0} RUNNING · ${data.counts.queued||0} QUEUED · ${data.counts.paused||0} PAUSED`:'NO ACTIVE TASK';$('#taskCenterList').innerHTML=items.length?items.slice(0,8).map(item=>{const project=state.engagements.find(e=>e.id===item.engagement_id),remaining=item.remaining_stages.length?`剩余 ${item.remaining_stages.length} 阶段：${item.remaining_stages.map(x=>stages.find(s=>s[0]===x)?.[1]||x).join('、')}`:'8 个阶段已结束',heartbeat=item.quiet_seconds<60?`${item.quiet_seconds}秒前`:`${Math.floor(item.quiet_seconds/60)}分前`;return `<button class="task-center-row ${item.id===state.activeRun?.id?'active':''} ${item.stalled?'stalled':''}" onclick="selectRun('${esc(item.id)}')"><span class="task-state-dot ${esc(item.status)}"></span><div><b>${esc(project?.name||item.id)}</b><small>${esc(item.last_event)}</small><p>${esc(remaining)}</p></div><div class="task-center-meta"><strong>${esc(runStatusText[item.status]||item.status)}</strong><small>心跳 ${heartbeat}${item.queue_position?` · 队列 #${item.queue_position}`:''}</small><span>${esc(item.next_action)}</span></div></button>`}).join(''):'<div class="empty-state">创建任务后，这里会显示排队、阶段、心跳和下一步。</div>'}
async function loadHttpWorkbench(){const panel=$('#httpWorkbench'),run=state.activeRun;if(!panel)return;panel.hidden=!run||run.mode!=='traditional';if(panel.hidden){state.httpExchanges=[];state.httpSelected=null;return}try{const [items,identities]=await Promise.all([api(`/api/v1/traditional/runs/${run.id}/http-exchanges`),api(`/api/v1/engagements/${run.engagement_id}/identities`)]);state.httpExchanges=items;if(state.httpSelected&&!items.some(item=>item.id===state.httpSelected.id))state.httpSelected=null;$('#httpIdentity').innerHTML='<option value="">无身份 / 手工 Header</option>'+identities.map(item=>`<option value="${esc(item.id)}" ${item.session_status!=='ready'?'disabled':''}>${esc(item.label)} · ${esc(item.role)}${item.tenant?` / ${esc(item.tenant)}`:''} · ${item.session_status==='ready'?'READY':'需登录'}</option>`).join('');renderHttpWorkbench()}catch(e){$('#httpMessage').textContent=e.message}}
function renderHttpWorkbench(){const items=state.httpExchanges||[],selected=state.httpSelected;$('#httpExchangeCount').textContent=`${items.length} EXCHANGES`;$('#httpExchangeList').innerHTML=items.length?items.map(item=>`<button type="button" class="http-exchange-row ${selected?.id===item.id?'active':''}" onclick="selectHttpExchange('${esc(item.id)}')"><span class="http-method">${esc(item.method)}</span><div><b>${esc(item.url)}</b><small>${new Date(item.created_at).toLocaleString()} · ${esc(item.source)}${item.parent_exchange_id?' · REPLAY':''}</small></div><strong class="status-${Math.floor(item.response_status/100)}xx">${item.response_status}</strong></button>`).join(''):'<div class="empty-state">还没有受控 HTTP 记录。填写授权范围内的 URL 后发送。</div>';if(!selected){$('#httpExchangeDetail').innerHTML='<div class="empty-state">选择一条请求查看响应摘要、哈希与重放差异。</div>';$('#replayHttp').disabled=true;return}const diff=selected.diff;$('#replayHttp').disabled=false;$('#httpExchangeDetail').innerHTML=`<header><div><small>EXCHANGE EVIDENCE</small><h3>${esc(selected.method)} · HTTP ${selected.response_status}</h3></div><span>${selected.response_bytes} bytes</span></header><dl><div><dt>URL</dt><dd>${esc(selected.url)}</dd></div><div><dt>Response SHA-256</dt><dd>${esc(selected.response_sha256)}</dd></div>${selected.parent_exchange_id?`<div><dt>Parent</dt><dd>${esc(selected.parent_exchange_id)}</dd></div>`:''}</dl><h4>响应摘要</h4><pre>${esc(selected.response_body_preview||'(empty response)')}</pre>${diff?`<section class="http-diff"><h4>与原请求对比</h4><p>${diff.status_changed?'状态码已变化':'状态码未变化'} · ${diff.body_changed?'响应内容已变化':'响应内容未变化'} · ${diff.bytes_delta>=0?'+':''}${diff.bytes_delta} bytes</p><pre>${esc(diff.preview||'没有文本差异')}</pre></section>`:''}<section class="candidate-from-http"><h4>加入 Candidate</h4><input id="httpCandidateTitle" placeholder="候选标题，例如：对象越权读取"><input id="httpCandidateCategory" placeholder="分类，例如：IDOR"><textarea id="httpCandidateHypothesis" rows="3" placeholder="说明观察到的行为和需要独立复验的假设"></textarea><button type="button" class="quiet-button" onclick="promoteHttpCandidate('${esc(selected.id)}')">建立候选记录</button></section>`}
window.selectHttpExchange=id=>{const item=state.httpExchanges.find(value=>value.id===id);if(!item)return;state.httpSelected=item;$('#httpMethod').value=item.method;$('#httpUrl').value=item.url;const reusable=Object.fromEntries(Object.entries(item.request_headers||{}).filter(([,value])=>value!=='[REDACTED]'));$('#httpHeaders').value=JSON.stringify(reusable,null,2);$('#httpBody').value=item.request_body||'';$('#httpIdentity').value=item.identity_id||'';renderHttpWorkbench()};
function httpEditorPayload(){let headers;try{headers=JSON.parse($('#httpHeaders').value||'{}')}catch{throw new Error('Headers 必须是 JSON 对象')}if(!headers||Array.isArray(headers)||typeof headers!=='object')throw new Error('Headers 必须是 JSON 对象');return {method:$('#httpMethod').value,url:$('#httpUrl').value.trim(),headers,body:$('#httpBody').value||null,identity_id:$('#httpIdentity').value||null}}
$('#httpRequestForm').onsubmit=async ev=>{ev.preventDefault();const message=$('#httpMessage');message.textContent='发送中…';try{const created=await api(`/api/v1/traditional/runs/${state.activeRun.id}/http-exchanges`,{method:'POST',body:JSON.stringify(httpEditorPayload())});await loadHttpWorkbench();selectHttpExchange(created.id);message.textContent=`已记录 ${created.method} · HTTP ${created.response_status}`;toast('受控 HTTP 请求已记录')}catch(e){message.textContent=e.message}};
$('#replayHttp').onclick=async()=>{if(!state.httpSelected)return;const message=$('#httpMessage');message.textContent='重放中…';try{const replay=await api(`/api/v1/traditional/http-exchanges/${state.httpSelected.id}/replay`,{method:'POST',body:JSON.stringify(httpEditorPayload())});await loadHttpWorkbench();state.httpSelected=replay;renderHttpWorkbench();message.textContent=replay.diff.body_changed?'重放完成，响应存在差异':'重放完成，响应未变化';toast('重放与 Diff 已完成')}catch(e){message.textContent=e.message}};
window.promoteHttpCandidate=async id=>{const title=$('#httpCandidateTitle').value.trim(),category=$('#httpCandidateCategory').value.trim(),hypothesis=$('#httpCandidateHypothesis').value.trim();if(title.length<3||category.length<2||hypothesis.length<3)return toast('请完整填写候选标题、分类和判断依据');try{await api(`/api/v1/traditional/http-exchanges/${id}/candidate`,{method:'POST',body:JSON.stringify({title,category,hypothesis})});await selectRun(state.activeRun.id);toast('HTTP 证据已加入 Candidate，仍需独立复验')}catch(e){toast(e.message)}};
async function selectRun(id){const run=state.runs.find(r=>r.id===id);if(!run)return;state.activeRun=run;state.httpSelected=null;$('#runSelector').value=id;$('#findingRunSelector').value=id;const [findings,coverage,details]=await Promise.all([api(`/api/v1/findings?mode=${state.mode}&run_id=${id}`),api(`/api/v1/runs/${id}/coverage`),api(`/api/v1/runs/${id}/details`)]);state.findings=findings;state.coverage=coverage.coverage||[];state.runDetails=details;renderFindings();renderRun();renderCoverage();await Promise.all([loadRunReport(id),loadHttpWorkbench()]);if(!terminalRunStates.has(run.status))poll()}
$('#runSelector').onchange=ev=>selectRun(ev.target.value);$('#findingRunSelector').onchange=ev=>selectRun(ev.target.value);
async function loadRunReport(id){try{const report=await api(`/api/v1/runs/${id}/summary-report`);if(state.activeRun?.id!==id)return;state.runReport=report;const r=state.runReport,c=r.counts,statusText={completed:'完成',failed:'失败',not_tested:'未测试',queued:'等待',running:'运行中'},coverageText={tested:'已测试',not_tested:'未测试',denied:'策略拒绝',failed:'失败'};$('#runSummary').innerHTML=`<div><small>本次结论</small><h2>${esc(r.verdict)}</h2><p>${c.candidates} 个候选 · ${c.verified} 个已验证 · ${c.completed_tests}/${c.tests} 个测试项完成 · ${c.tested}/${c.coverage} 个覆盖项已测试</p></div>`;$('#runReportPanel').innerHTML=`<header class="report-panel-header"><div><p class="eyebrow">RUN REPORT</p><h2>${c.verified?'漏洞与覆盖报告':'零已验证漏洞 · 测试覆盖报告'}</h2><p>${esc(r.target)} · 本报告陈述实际执行反馈，不把“未发现”解释为“绝对安全”。</p></div><span class="state-badge ${r.status==='completed'?'ready':''}">${esc(r.status)}</span></header><div class="report-stat-strip"><div><small>计划测试</small><strong>${c.tests}</strong></div><div><small>完成</small><strong>${c.completed_tests}</strong></div><div><small>失败</small><strong>${c.failed_tests}</strong></div><div><small>未测试</small><strong>${c.not_tested}</strong></div><div><small>Observation</small><strong>${r.tests.reduce((sum,item)=>sum+(item.observation_count||0),0)}</strong></div></div><details class="report-detail"><summary><span>实际测试与反馈</span><b>${c.tests} 项</b></summary><div class="report-test-list">${r.tests.length?r.tests.map((item,index)=>`<article class="report-test-row ${esc(item.status)}"><span class="report-test-index">${String(index+1).padStart(2,'0')}</span><div><h3>${esc(item.label)}</h3><p>${esc(item.description)}</p><small>${esc(item.id)} · ${esc(item.result)}</small></div><div><strong>${esc(statusText[item.status]||item.status)}</strong><small>${item.observation_count} OBS</small></div></article>`).join(''):'<div class="empty-state">本次运行没有形成可核验的测试项记录。</div>'}</div></details><details class="report-detail"><summary><span>Coverage Ledger</span><b>${c.tested}/${c.coverage} 已测试</b></summary><div class="report-coverage-list">${r.coverage.length?r.coverage.map(item=>`<article><div><b>${esc(item.surface_key)}</b><p>${esc(item.reason)}</p></div><span class="state-badge ${item.state==='tested'?'ready':''}">${esc(coverageText[item.state]||item.state)}</span></article>`).join(''):'<div class="empty-state">没有覆盖账本记录；不能据此推断目标安全。</div>'}</div></details>`;$('#downloadRunReport').disabled=false}catch{if(state.activeRun?.id!==id)return;$('#runSummary').innerHTML='<div class="empty-state">选择一次运行以查看总结。</div>';$('#runReportPanel').innerHTML='<div class="empty-state">当前运行尚未生成测试与覆盖报告。</div>';$('#downloadRunReport').disabled=true}}
$('#downloadRunReport').onclick=()=>{if(!state.runReport)return;const blob=new Blob([state.runReport.content],{type:'text/markdown;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${state.runReport.name}-${state.runReport.run_id}.md`;a.click();URL.revokeObjectURL(a.href)};
window.saveCandidate=async id=>{const card=$(`[data-finding="${id}"]`);try{await api(`/api/v1/findings/${id}`,{method:'PATCH',body:JSON.stringify({title:card.querySelector('.finding-title-input').value,hypothesis:card.querySelector('.hypothesis-input').value})});await selectRun(state.activeRun.id);toast('候选记录已更新')}catch(e){toast(e.message)}};
window.saveVerified=async id=>{const card=$(`[data-finding="${id}"]`);try{await api(`/api/v1/findings/${id}`,{method:'PATCH',body:JSON.stringify({title:card.querySelector('.finding-title-input').value,severity:card.querySelector('.severity-input').value})});await selectRun(state.activeRun.id);toast('漏洞记录已更新')}catch(e){toast(e.message)}};
window.openFindingLifecycle=async id=>{let dialog=$('#findingLifecycleDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='findingLifecycleDialog';dialog.className='lifecycle-dialog';document.body.append(dialog)}const load=async()=>{const data=await api(`/api/v1/findings/${id}/lifecycle`),runs=state.runs.filter(run=>run.engagement_id===data.engagement_id&&run.id!==data.last_seen_run_id),statusLabel={open:'仍存在',fix_claimed:'已声明修复',retest_required:'等待复测',reopened:'复测仍可复现',verified_fixed:'复测确认修复'};dialog.innerHTML=`<div class="dialog-top"><div><p class="eyebrow">FINDING LIFECYCLE</p><h2>修复与定向复测</h2></div><button type="button" class="close-button" id="closeFindingLifecycle" aria-label="关闭">×</button></div><section class="lifecycle-summary"><div><small>当前状态</small><strong>${esc(statusLabel[data.status]||data.status)}</strong></div><div><small>首次 / 最近 Run</small><strong>${esc(data.first_seen_run_id)}<br>${esc(data.last_seen_run_id)}</strong></div><div><small>同根因出现</small><strong>${esc(data.occurrence_count)} 次</strong></div></section><form id="findingFixForm" class="lifecycle-form"><label>修复版本、提交或措施<textarea id="findingRemediation" required rows="3" placeholder="例如：commit abc123 在对象查询中增加 tenant_id 条件">${esc(data.remediation?.description||'')}</textarea></label><label>记录说明<textarea id="findingLifecycleNote" rows="2" placeholder="修复环境、部署版本或需要保留的上下文"></textarea></label><div class="dialog-actions"><button type="button" class="quiet-button" id="keepFindingOpen">保持开放</button><button type="submit" class="primary-action compact">记录修复声明</button></div></form><section class="retest-planner"><h3>安排同根因复测</h3><p>选择同一项目的新版运行。系统会复制原始根因生成定向候选；真实 Oracle 再次复现会重开，连续两轮明确拒绝旧攻击才确认修复。</p><div><select id="findingRetestRun" aria-label="选择复测运行">${runs.map(run=>`<option value="${esc(run.id)}">${esc(run.id)} · ${esc(run.status)}</option>`).join('')||'<option value="">暂无可用运行</option>'}</select><button type="button" class="quiet-button" id="planFindingRetest" ${runs.length?'':'disabled'}>创建并打开复测候选</button></div></section><section class="lifecycle-history"><h3>状态历史</h3>${data.history.slice().reverse().slice(0,8).map(item=>`<article><b>${esc(statusLabel[item.kind]||item.kind)}</b><span>${new Date(item.at).toLocaleString()}</span><small>${esc(item.note||item.run_id||'')}</small></article>`).join('')}</section><p class="asset-boundary">${esc(data.fixed_gate)}</p><p id="findingLifecycleError" class="inline-error" role="status"></p>`;dialog.querySelector('#closeFindingLifecycle').onclick=()=>dialog.close();dialog.querySelector('#findingFixForm').onsubmit=async event=>{event.preventDefault();try{await api(`/api/v1/findings/${id}/lifecycle`,{method:'PATCH',body:JSON.stringify({status:'fix_claimed',remediation:dialog.querySelector('#findingRemediation').value,note:dialog.querySelector('#findingLifecycleNote').value})});await refresh();await load();toast('修复声明已记录，Finding 等待复测')}catch(error){dialog.querySelector('#findingLifecycleError').textContent=error.message}};dialog.querySelector('#keepFindingOpen').onclick=async()=>{try{await api(`/api/v1/findings/${id}/lifecycle`,{method:'PATCH',body:JSON.stringify({status:'open',note:dialog.querySelector('#findingLifecycleNote').value})});await refresh();await load();toast('Finding 保持开放')}catch(error){dialog.querySelector('#findingLifecycleError').textContent=error.message}};dialog.querySelector('#planFindingRetest').onclick=async()=>{const runId=dialog.querySelector('#findingRetestRun').value;if(!runId)return;try{const planned=await api(`/api/v1/findings/${id}/retest-plans`,{method:'POST',body:JSON.stringify({run_id:runId,note:dialog.querySelector('#findingLifecycleNote').value||'按原始根因与安全边界执行定向复测'})});dialog.close();await refresh();go('findings');await selectRun(runId);await openCandidateDetail(planned.candidate_id);toast('已打开新 Run 的定向复测候选')}catch(error){dialog.querySelector('#findingLifecycleError').textContent=error.message}}};try{await load();if(!dialog.open)dialog.showModal()}catch(error){toast(error.message)}};
window.archiveFinding=async id=>{if(!confirm('归档后该记录不再出现在结果与报告选择器中。继续吗？'))return;try{await api(`/api/v1/findings/${id}`,{method:'DELETE'});await selectRun(state.activeRun.id);toast('记录已归档')}catch(e){toast(e.message)}};
$('#clearRunCandidates').onclick=()=>{if(!state.activeRun||!state.findings.candidates.length)return;$('#clearCandidatesDialog').showModal()};
