$('#closeClearCandidates').onclick=closeClearCandidates;$('#cancelClearCandidates').onclick=closeClearCandidates;
$('#clearCandidatesForm').onsubmit=async ev=>{ev.preventDefault();if(!state.activeRun)return;const button=$('#confirmClearCandidates');button.disabled=true;button.textContent='正在清除…';try{const result=await api(`/api/v1/runs/${state.activeRun.id}/findings/archive-candidates`,{method:'POST'});closeClearCandidates();await selectRun(state.activeRun.id);toast(`已清除 ${result.archived} 条候选；测试报告与证据仍保留`)}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='清除当前候选'}};
function renderCoverage(){const box=$('#coverageList');if(!box)return;$('#clearCoverage').disabled=!state.activeRun||!state.coverage.length;box.innerHTML=state.coverage.length?state.coverage.map(item=>`<article class="candidate-row"><div><h3>${esc(item.surface_key)}</h3><p>${esc(item.reason)}</p></div><span class="state-badge ${item.state==='tested'?'ready':''}">${esc(item.state)}</span><span class="domain-label">${item.observation_ids?.length||0} OBS</span></article>`).join(''):'<div class="empty-state">运行工具后生成覆盖账本。</div>'}
$('#clearTaskCenter').onclick=async()=>{const terminal=(state.taskCenter?.items||[]).filter(item=>!['queued','running','paused'].includes(item.status));if(!terminal.length)return;if(!confirm(`从任务中心隐藏 ${terminal.length} 条已结束记录？\n\n运行证据、漏洞结果和报告不会删除。`))return;try{const result=await api(`/api/v1/task-center?mode=${state.mode}`,{method:'DELETE',body:JSON.stringify({confirmation:'CLEAR_TERMINAL_TASKS'})});state.taskCenter=await api(`/api/v1/task-center?mode=${state.mode}`);renderTaskCenter();toast(`已清除 ${result.hidden} 条任务列表记录，证据与报告保留`)}catch(e){toast(e.message)}};
$('#clearCoverage').onclick=async()=>{if(!state.activeRun||!state.coverage.length)return;if(!confirm(`清除当前运行的 ${state.coverage.length} 条 Coverage Ledger 显示记录？\n\n底层 Observation、Evidence 和已编译报告保留；之后新产生的覆盖项会重新显示。`))return;try{const result=await api(`/api/v1/runs/${state.activeRun.id}/coverage-display`,{method:'DELETE',body:JSON.stringify({confirmation:'CLEAR_COVERAGE_DISPLAY'})});state.coverage=[];renderCoverage();toast(`已清除 ${result.hidden} 条覆盖列表记录，证据与报告保留`)}catch(e){toast(e.message)}};
const runStatusText={queued:'排队准备',running:'正在分析',paused:'已暂停',completed:'分析完成',stopped:'已停止',failed:'执行失败',timeout:'已超时',budget_exhausted:'预算耗尽'};
const terminalRunStates=new Set(['completed','stopped','failed','timeout','budget_exhausted']);
function elapsed(r){const start=r.started_at||r.created_at;if(!start)return '0秒';const end=r.completed_at||r.stopped_at||(terminalRunStates.has(r.status)?r.updated_at:null);const seconds=Math.max(0,Math.floor((new Date(end||Date.now())-new Date(start))/1000));if(seconds<60)return `${seconds}秒`;const minutes=Math.floor(seconds/60),rest=seconds%60;return `${minutes}分 ${rest}秒`}
function renderRunGuide(r,done){const guide=$('#runGuide'),stageLabel=stages.find(([key])=>key===r.current_stage)?.[1]||'准备执行',status=runStatusText[r.status]||r.status,lastEvent=r.events?.at(-1),lastTime=lastEvent?new Date(lastEvent.created_at).toLocaleTimeString():'等待首个事件';let title='',body='',actions='',kind='';if(['queued','running'].includes(r.status)){kind='running';title='真实工具链正在运行';body=`当前阶段：${esc(stageLabel)} · 已运行 ${elapsed(r)} · 最近事件 ${esc(lastTime)}。页面每秒同步一次，任务达到终态后会自动显示结果入口。`;actions='<span class="run-heartbeat"><i></i>连接正常，等待执行事件</span>'}else if(r.status==='paused'){kind='paused';title='分析已暂停';body=`已完成 ${done.size}/8 个阶段，运行上下文仍保留。恢复后将继续接收执行事件。`;actions='<button class="quiet-button" onclick="control(\'resume\')">恢复分析</button>'}else if(r.status==='completed'){kind='complete';title='真实分析已完成';body=`工具链已结束，共记录 ${state.findings.candidates.length} 个候选、${state.findings.verified.length} 个已验证漏洞。候选不等于漏洞，只有独立复验通过的项目才会进入报告。`;actions='<button class="primary-action compact" onclick="viewResults()"><span>查看漏洞结果</span><b>→</b></button><button class="quiet-button" onclick="viewReports()">查看报告中心</button>'}else{kind='warning';title=status;body=`任务已结束，已完成 ${done.size}/8 个阶段，用时 ${elapsed(r)}。可在事件流查看原因，修正后重新运行。`;actions='<button class="quiet-button" onclick="rerunReal()">重新启动真实分析</button>'}guide.className=`run-guide ${kind}`;guide.innerHTML=`<div><small>当前状态</small><h2>${esc(title)}</h2><p>${body}</p></div><div class="run-guide-actions">${actions}</div>`}
function renderRun(){const r=state.activeRun||state.runs[0],details=state.runDetails,stageRows=details?.stages||stages.map(([id,label])=>({id,label,status:r?.current_stage===id?'running':'queued',summary:'等待运行详情'})),done=new Set(stageRows.filter(s=>s.status==='completed').map(s=>s.id)),statusLabel={human_review:'待复验',not_applicable:'不适用',completed:'DONE',running:'ACTIVE',queued:'WAIT',paused:'PAUSED',failed:'FAILED',not_tested:'NOT TESTED',stopped:'STOPPED'};$('#runTimeline').innerHTML=stageRows.map((stage,i)=>{const items=details?.test_items?.filter(item=>item.stage===stage.id)||[],observations=stage.id==='processing'?(details?.observations||[]):[];return `<li class="stage-row ${stage.status==='completed'?'done':''} ${stage.status==='running'?'current':''} ${stage.status==='failed'?'failed':''}"><span class="timeline-index">${String(i+1).padStart(2,'0')}</span><details class="stage-detail" ${(stage.status==='running'||stage.status==='failed'||items.length||observations.length)?'open':''}><summary><div><h3>${esc(stage.label)}</h3><p>${esc(stage.summary)}</p></div><span class="detail-toggle">展开详情</span></summary><div class="stage-items">${items.length?items.map(item=>`<article class="test-item ${esc(item.status)}"><div><b>${esc(item.label)}</b><p>${esc(item.description)}</p><small>${esc(item.result)}</small></div><span><strong>${esc(statusLabel[item.status]||item.status)}</strong><small>${item.observation_count} OBS</small></span></article>`).join(''):''}${observations.length?observations.map(obs=>`<article class="test-item completed"><div><b>${esc(obs.source_capability)} · ${esc(obs.observation_type)}</b><p>${esc(obs.summary)}</p><small>${esc(obs.subject)}</small></div><span><strong>${Math.round(obs.confidence*100)}%</strong><small>CONFIDENCE</small></span></article>`).join(''):''}${!items.length&&!observations.length?'<p class="stage-empty">该阶段没有独立工具项，状态由运行合同与上游证据确定。</p>':''}</div></details><span class="status-label">${esc(statusLabel[stage.status]||stage.status)}</span></li>`}).join('');if(!r){$('#runMetrics').innerHTML='<div class="metric"><small>状态</small><strong>-</strong></div>';$('#runGuide').className='run-guide empty';$('#runGuide').innerHTML='<div><small>当前状态</small><h2>没有运行中的任务</h2><p>从新建分析创建目标并确认授权范围后，执行状态会在这里实时更新。</p></div>';return}state.activeRun=r;$('#runTitle').textContent=`${r.mode==='web3'?'Web3':'Traditional'} analysis`;$('#runSubtitle').textContent=`${r.id} · Scope ${r.scope_snapshot_id}`;$('#runStatus').textContent=runStatusText[r.status]||r.status;$('#runMetrics').innerHTML=`<div class="metric"><small>运行状态</small><strong>${esc(runStatusText[r.status]||r.status)}</strong></div><div class="metric"><small>已完成阶段</small><strong>${done.size}/8</strong></div><div class="metric"><small>已运行</small><strong>${elapsed(r)}</strong></div><div class="metric"><small>候选 / 已验证</small><strong>${state.findings.candidates.length} / ${state.findings.verified.length}</strong></div><div class="metric"><small>实际测试项</small><strong>${details?.test_items?.length||0}</strong></div>`;renderRunGuide(r,done);$('#pauseRun').disabled=r.status!=='running';$('#resumeRun').disabled=r.status!=='paused';$('#stopRun').disabled=!['queued','running','paused'].includes(r.status);$('#activityFeed').innerHTML=r.events?.length?r.events.slice().reverse().map(e=>`<div class="activity-item"><time>${new Date(e.created_at).toLocaleTimeString()}</time><div><b>${esc(e.payload?.label||e.kind)}</b><span>${esc(e.message)}</span></div></div>`).join(''):'<div class="empty-state">等待第一个运行事件。</div>';$('#rawRunData').textContent=JSON.stringify({run:r,details},null,2)}
window.rerunReal=async()=>{const r=state.activeRun;if(!r)return toast('没有可重启的任务');if(r.mode!=='traditional')return toast('当前真实工具链仅支持 Traditional 模式');if(state.mode!=='traditional')setMode('traditional');await startRun(r.engagement_id)};
window.viewResults=async()=>{go('findings');if(state.activeRun)await selectRun(state.activeRun.id)};window.viewReports=()=>go('reports');
async function control(action){if(!state.activeRun)return toast('没有可控制的任务');try{state.activeRun=await api(`/api/v1/runs/${state.activeRun.id}/${action}`,{method:'POST'});renderRun();toast({'pause':'分析已暂停','resume':'分析已恢复','stop':'分析已停止'}[action]);if(action==='resume')poll()}catch(e){toast(e.message)}}$('#pauseRun').onclick=()=>control('pause');$('#resumeRun').onclick=()=>control('resume');$('#stopRun').onclick=()=>control('stop');
async function loadTools(){try{const [a,provider,readiness]=await Promise.all([api('/api/v1/capabilities'),api('/api/v1/traditional/provider'),api('/api/v1/runtime/readiness')]),agent=readiness.native_agent;$('#toolGrid').innerHTML=[{...agent,domain:'agent',detail:'Scope 与预算约束的 Chrome 只读研究 Agent',version:agent.browser},...a].map(c=>{const optional=c.requires_docker,status=optional?(c.ready?'OPTIONAL READY':'OPTIONAL · DOCKER'):!c.available?'MISSING':!c.configured?'CONFIG REQUIRED':'READY';return `<article class="tool-card"><header><h3>${esc(c.id)}</h3><span class="availability ${(c.ready??(c.available&&c.configured))?'on':''}"></span></header><p>${esc(c.detail)}</p><small>${esc(c.version||'未探测到版本')}</small><span class="domain-label">${esc(c.domain)} · ${status}</span></article>`}).join('');if(provider.base_url&&!$('#providerBase').value)$('#providerBase').value=provider.base_url;if(provider.model&&!$('#providerModel').value)$('#providerModel').value=provider.model.replace(/^openai\//,'');$('#providerBadge').textContent=provider.configured?'CONFIGURED':'OPTIONAL';$('#providerBadge').classList.toggle('ready',provider.configured);$('#nativeState').textContent=readiness.ready?'Ready':'部分降级';$('#nativeHint').textContent=readiness.ready?`原生核心工具 ${readiness.available_core}/${readiness.required_core} 已就绪；Native Agent ${agent.ready?'Ready':'等待模型 API'}。`:`原生核心工具 ${readiness.available_core}/${readiness.required_core} 可用；缺失项会逐项标为未测试。`;}catch(e){toast(e.message)}}
let currentPreview=null;
$('#previewReport').onclick=async()=>{const finding=$('#reportFinding').value,platform=$('#reportPlatform').value;if(!finding)return toast('只有 Verified Finding 可以生成报告');try{currentPreview=await api(`/api/v1/findings/${finding}/reports/${platform}/preview`,{method:'POST'});$('#reportContent').textContent=currentPreview.content;const c=currentPreview.completeness,recommended=c.missing_recommended||[];$('#completeness').innerHTML=`<div class="check-row"><span>必填材料完整度</span><b class="${c.ready?'ok':''}">${c.score}%</b></div>${c.required.map(x=>`<div class="check-row"><span>${esc(x)}</span><b class="${c.missing_required.includes(x)?'':'ok'}">${c.missing_required.includes(x)?'缺失':'✓'}</b></div>`).join('')}${recommended.length?`<div class="check-row report-recommendation"><span>建议补充</span><b>${recommended.length} 项</b></div>${recommended.map(x=>`<div class="check-row"><span>${esc(x)}</span><b>建议</b></div>`).join('')}`:''}`;$('#exportReport').disabled=false;toast(c.ready?(recommended.length?'必填项已齐，仍有建议材料可补充':'预览已通过完整性检查'):'预览已生成，缺失字段未被编造')}catch(e){toast(e.message)}};
$('#exportReport').onclick=async()=>{if(!currentPreview)return;try{const r=await api(`/api/v1/findings/${currentPreview.finding_id}/reports/${currentPreview.platform}/export`,{method:'POST'});const a=document.createElement('a');a.href=r.download_url;a.download=`${r.id}.zip`;a.click();toast('材料包已生成，仍需人工提交')}catch(e){toast(e.message)}};
const maintenance=document.createElement('section');maintenance.className='maintenance-section';maintenance.innerHTML='<div class="section-heading"><div><h2>本地数据维护</h2><p>缓存可重新生成；近期记录包含项目、任务、候选、证据和报告。</p></div></div><div class="maintenance-actions"><div><h3>运行缓存</h3><p>删除 Agent 临时工作目录与仓库检出，不删除漏洞证据或报告。</p><button id="clearCache" class="quiet-button">清理缓存</button></div><div><h3>近期记录</h3><p>清空全部本地项目记录和证据文件；执行前自动创建可恢复数据库备份。</p><button id="clearRecent" class="danger-button">清空近期记录</button></div></div><p id="maintenanceMessage" class="inline-error" role="status"></p>';$('#expertSettings').before(maintenance);
$('#clearCache').onclick=async()=>{if(!confirm('清理 Agent 临时目录和仓库检出？漏洞证据与报告不会删除。'))return;const message=$('#maintenanceMessage');try{const result=await api('/api/v1/maintenance/cache/clear',{method:'POST',body:JSON.stringify({confirmation:'CLEAR_CACHE'})});message.textContent=`已清理 ${result.removed_files} 个缓存文件，释放 ${(result.removed_bytes/1048576).toFixed(1)} MB。`;toast('缓存清理完成')}catch(e){message.textContent=e.message}};
$('#clearRecent').onclick=async()=>{if(!confirm('这会清空全部项目、任务、候选、证据与报告记录。系统会先创建数据库备份。继续吗？'))return;const typed=prompt('请输入“清空”确认此操作');if(typed!=='清空')return;const message=$('#maintenanceMessage');try{const result=await api('/api/v1/maintenance/recent-records',{method:'DELETE',body:JSON.stringify({confirmation:'CLEAR_RECENT_RECORDS'})});state.activeRun=null;state.runs=[];state.engagements=[];state.findings={verified:[],candidates:[]};message.textContent=`近期记录已清空；恢复备份：${result.backup}`;await refresh();toast('近期记录已清空并完成备份')}catch(e){message.textContent=e.message}};
const assetGraph=document.createElement('section');assetGraph.id='assetGraph';assetGraph.className='asset-graph';assetGraph.hidden=true;assetGraph.innerHTML='<div class="section-heading"><div><p class="eyebrow">PROJECT SURFACE</p><h2>项目资产关系</h2><p>把目标、环境、入口、源码与部署按 Observation 来源组织起来。</p></div><span id="assetGraphCount" class="status-label">0 ASSETS</span></div><div id="assetGraphContent"><div class="empty-state">选择一次运行以查看项目资产。</div></div>';$('#httpWorkbench').before(assetGraph);
async function loadAssetGraph(){const run=state.activeRun,panel=$('#assetGraph');panel.hidden=!run;if(!run)return;try{const graph=await api(`/api/v1/engagements/${run.engagement_id}/asset-graph`),root=graph.nodes.find(item=>item.id===graph.root_id),groups=Object.entries(graph.nodes.filter(item=>item.id!==graph.root_id).reduce((all,item)=>{(all[item.entity_type]??=[]).push(item);return all},{})).sort((a,b)=>b[1].length-a[1].length);$('#assetGraphCount').textContent=`${graph.counts.nodes} ASSETS · ${graph.counts.edges} LINKS`;$('#assetGraphContent').innerHTML=`<article class="asset-root"><small>授权根目标 · ${esc(root?.attributes?.environment_class||'未标注环境')}</small><strong>${esc(root?.label||'目标不可用')}</strong><span>${esc(root?.attributes?.target_type||graph.mode)}</span></article>${groups.length?`<div class="asset-groups">${groups.map(([type,items])=>`<section><header><b>${esc(type)}</b><span>${items.length}</span></header>${items.slice(0,8).map(item=>`<article class="${item.attributes?.scope_status==='outside_root'?'outside-root':''}"><i></i><div><strong>${esc(item.label)}</strong><small>${esc(item.attributes?.source||'已记录来源')} · ${Math.round(Number(item.attributes?.confidence||0)*100)}%${item.attributes?.scope_status==='outside_root'?' · 根目标外观察':''}</small></div></article>`).join('')}${items.length>8?`<p>另有 ${items.length-8} 项，保留在完整关系数据中。</p>`:''}</section>`).join('')}</div>`:'<div class="empty-state">尚无资产 Observation；根目标已冻结，但不能视为已完成资产发现。</div>'}<p class="asset-boundary">${esc(graph.boundary)}</p>`}catch(error){$('#assetGraphCount').textContent='DEGRADED';$('#assetGraphContent').innerHTML=`<div class="empty-state">${esc(error.message)}</div>`}}
const web3Discovery=document.createElement('section');web3Discovery.id='web3Discovery';web3Discovery.className='web3-discovery';web3Discovery.hidden=true;web3Discovery.innerHTML='<div class="section-heading"><div><p class="eyebrow">WEB3 ATTACK SURFACE</p><h2>合约发现与检索</h2><p>从 ABI、源码和危险原语建立入口点、协议关系、不变量与待验证假设。</p></div><span id="web3DiscoveryState" class="status-label">WAITING</span></div><div id="web3DiscoveryContent"><div class="empty-state">Web3 源码模型生成后显示攻击面。</div></div>';$('#coverageList').closest('.finding-section').before(web3Discovery);
async function loadWeb3Discovery(){const run=state.activeRun,panel=$('#web3Discovery');panel.hidden=!run||run.mode!=='web3';if(panel.hidden)return;try{const data=await api(`/api/v1/web3/runs/${run.id}/discovery`);if(!data.ready){$('#web3DiscoveryState').textContent='WAITING';$('#web3DiscoveryContent').innerHTML='<div class="empty-state">当前 Run 还没有生成 Web3 源码模型。运行 Forge 编译与源码检查后，这里会建立可检索攻击面。</div>';return}const s=data.summary||{},severity={critical:'CRITICAL',high:'HIGH',medium:'MEDIUM',low:'LOW'};$('#web3DiscoveryState').textContent=`${s.hypotheses||0} HYPOTHESES`;$('#web3DiscoveryContent').innerHTML=`<div class="web3-discovery-stats"><div><small>合约</small><strong>${s.contracts||0}</strong></div><div><small>外部入口</small><strong>${s.entrypoints||0}</strong></div><div><small>状态变量</small><strong>${s.state_variables||0}</strong></div><div><small>调用边</small><strong>${s.call_edges||0}</strong></div><div><small>风险路径</small><strong>${s.risk_paths||0}</strong></div><div><small>危险原语</small><strong>${s.risk_primitives||0}</strong></div></div><div class="web3-discovery-grid"><section><h3>入口点与状态读写</h3><div class="web3-entrypoints">${data.entrypoints.length?data.entrypoints.sort((a,b)=>(b.risk_score||0)-(a.risk_score||0)).map(item=>`<article><div><b>${esc(item.contract)}.${esc(item.signature)}</b><small>${esc(item.source)}</small><small class="semantic-line">W ${item.writes?.length?esc(item.writes.join(' · ')):'—'} &nbsp; R ${item.reads?.length?esc(item.reads.join(' · ')):'—'}${item.external_calls?.length?`<br>CALL ${esc(item.external_calls.join(' · '))}`:''}</small></div><span class="risk-score">${item.risk_score||0}</span><em>${item.guards.length?esc(item.guards.join(' · ')):'NO KNOWN GUARD'}</em></article>`).join(''):'<div class="empty-state">没有发现 public/external 入口点。</div>'}</div></section><section><h3>优先验证假设</h3><div class="web3-hypotheses">${data.hypotheses.length?data.hypotheses.map(item=>`<article class="${esc(item.severity)}"><span>${severity[item.severity]||esc(item.severity)}</span><div><b>${esc(item.subject)}</b><p>${esc(item.statement)}</p><small>${esc(item.proof_required)}</small></div></article>`).join(''):'<div class="empty-state">未命中确定性高风险原语；这不代表合约安全。</div>'}</div></section></div><p class="web3-discovery-boundary">${esc(data.boundary)}</p>`}catch(error){$('#web3DiscoveryState').textContent='DEGRADED';$('#web3DiscoveryContent').innerHTML=`<div class="empty-state">${esc(error.message)}</div>`}}
const loadWeb3DiscoveryBase=loadWeb3Discovery;loadWeb3Discovery=async()=>{await loadWeb3DiscoveryBase();const run=state.activeRun;if(!run||run.mode!=='web3'||$('#web3Discovery').hidden)return;try{const data=await api(`/api/v1/web3/runs/${run.id}/discovery`);if(!data.ready)return;if(data.risk_paths?.length){const semantic=document.createElement('section');semantic.className='web3-semantic-paths';semantic.innerHTML=`<div><p class="eyebrow">SEMANTIC RISK PATHS</p><h3>状态 → 外部交互</h3><p>优先复核同一可达入口中的状态写入、外部调用与权限保护。</p></div><div>${data.risk_paths.map(item=>`<article><span>${esc(item.severity)}</span><div><b>${esc(item.entrypoint)}</b><p>WRITE ${esc(item.writes.join(' · '))}</p><p>CALL ${esc(item.calls.join(' · '))}</p><small>${item.guards.length?`GUARD ${esc(item.guards.join(' · '))}`:'NO KNOWN GUARD · verify CEI and callback reachability'}</small></div></article>`).join('')}</div>`;$('#web3DiscoveryContent').append(semantic)}if(data.property_tests?.length){const failed=data.property_tests.filter(item=>!['success','passed'].includes(String(item.status).toLowerCase())),section=document.createElement('section');section.className='web3-property-evidence';section.innerHTML=`<div><p class="eyebrow">DYNAMIC PROPERTY EVIDENCE</p><h3>属性测试与模糊反例</h3><p>Forge 真实执行 ${data.property_tests.length} 个属性；${failed.length} 个产生反例。</p></div><div>${data.property_tests.map(item=>`<article class="${['success','passed'].includes(String(item.status).toLowerCase())?'passed':'failed'}"><span>${esc(item.status)}</span><div><b>${esc(item.name)}</b><p>${esc(item.reason||`${item.fuzz_runs||0} fuzz runs`)}</p><small>${esc(item.suite)}${item.counterexample?` · counterexample retained in redacted artifact`:''}</small></div></article>`).join('')}</div>`;$('#web3DiscoveryContent').append(section)}}catch{}};
const selectRunBase=selectRun;selectRun=async id=>{await selectRunBase(id);await Promise.all([loadWeb3Discovery(),loadAssetGraph()])};
let path=location.pathname.split('/')[1];if(path==='runs')path='run';if(['new','run','findings','reports','settings'].includes(path))go(path);setMode(state.mode);
